CREATE OR REPLACE FUNCTION public.media_submission_save_draft(p_submission uuid, p_data jsonb, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions; o submission_media.operations; f record;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);
 o:=submission_media.begin_operation(s.id,'save_workspace_draft',p_key,jsonb_build_object('data',p_data,'revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or p_revision<>s.workspace_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if exists(select 1 from submission_media.master_reviews where submission_id=s.id and state='pending') or (s.track_id is not null and not exists(select 1 from public.tracks where id=s.track_id and status='draft')) then raise exception 'Submitted workspace is read only' using errcode='42501';end if;
 if p_data is null or jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>40000 or (p_data-array['title','primaryArtist','featuredArtists','description','genre','subgenre','bpm','key','moods','language','releaseTitle','releaseDate','releaseYear','masterOwnership','masterOwners','publishingOwners','authority','hasSamples','samples','hasClaims','claims','hasAgreements','agreements','publishingOwnership','licensingAuthority','rightsNotes','permittedUses','restrictions','territories','licenseDuration','explicit','vocal','releaseStatus','contributors','rightsDeclared','licenseCategories'])<>'{}'::jsonb then raise exception 'Invalid draft' using errcode='22023';end if;
 for f in select * from (values ('title',160),('primaryArtist',200),('featuredArtists',1000),('description',3000),('genre',80),('subgenre',80),('bpm',3),('key',40),('moods',500),('language',35),('releaseTitle',200),('releaseDate',10),('releaseYear',4),('masterOwnership',2000),('publishingOwnership',2000),('licensingAuthority',2000),('rightsNotes',2000),('permittedUses',1000),('restrictions',2000),('territories',500),('licenseDuration',200)) fields(name,maximum) loop
  if jsonb_typeof(p_data->f.name) is distinct from 'string' or length(p_data->>f.name)>f.maximum or (p_data->>f.name)~'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' then raise exception 'Invalid draft field' using errcode='22023';end if;
 end loop;
 if coalesce(p_data->>'explicit','') not in ('unknown','clean','explicit') or coalesce(p_data->>'vocal','') not in ('unknown','instrumental','vocal','mixed') or coalesce(p_data->>'releaseStatus','') not in ('unreleased','released') or jsonb_typeof(p_data->'rightsDeclared') is distinct from 'boolean' or jsonb_typeof(p_data->'contributors') is distinct from 'array' or jsonb_typeof(p_data->'licenseCategories') is distinct from 'array' then raise exception 'Invalid draft classification' using errcode='22023';end if;
 if jsonb_array_length(p_data->'contributors')>30 or jsonb_array_length(p_data->'licenseCategories')>3 then raise exception 'Draft limit' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_data->'licenseCategories') c where jsonb_typeof(c) is distinct from 'string' or c#>>'{}' not in ('digital','broadcast','exclusive')) or exists(select 1 from jsonb_array_elements(p_data->'contributors') c where jsonb_typeof(c) is distinct from 'object' or c-array['name','role']<>'{}'::jsonb or jsonb_typeof(c->'name') is distinct from 'string' or length(c->>'name')>200 or coalesce(c->>'role','') not in ('writer','composer','producer','publisher','performer','other')) then raise exception 'Invalid contributors or preferences' using errcode='22023';end if;
 if s.workspace_draft ? 'publishingOwners' and not p_data ? 'publishingOwners' then raise exception 'Reload the updated rights workspace before saving' using errcode='22023';end if;
 perform submission_media.validate_master_owners(p_data->'masterOwners',false);
 perform submission_media.validate_workspace_rights(s.id,p_data,false);
 update submission_media.submissions set workspace_draft=p_data,workspace_revision=workspace_revision+1 where id=s.id;
 perform submission_media.append_event(s.id,'upload_metadata_saved',null,o.id,null,null,'artist');
 return submission_media.finish_operation(o.id,jsonb_build_object('draft_revision',s.workspace_revision+1,'revision',submission_media.bump(s.id)));
end $function$

CREATE OR REPLACE FUNCTION public.media_upload_save_metadata(p_submission uuid, p_data jsonb, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare s submission_media.submissions; o submission_media.operations;t uuid;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);o:=submission_media.begin_operation(s.id,'save_upload_metadata',p_key,jsonb_build_object('data',p_data,'revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>12000 or (p_data-array['title','description','genre','subgenre','moods','bpm','key','releaseYear','instrumental','vocals','explicit'])<>'{}'::jsonb or coalesce(length(p_data->>'title'),0) not between 2 and 160 or coalesce(length(p_data->>'description'),0) not between 20 and 5000 or coalesce(length(p_data->>'genre'),0) not between 1 and 80 or coalesce(length(p_data->>'subgenre'),0) not between 1 and 80 or coalesce(length(p_data->>'moods'),0) not between 1 and 500 or coalesce(length(p_data->>'key'),0) not between 1 and 40 or coalesce(p_data->>'bpm','')!~'^[0-9]{2,3}$' or (p_data->>'bpm')::integer not between 40 and 220 or coalesce(p_data->>'releaseYear','')!~'^[0-9]{4}$' or (p_data->>'releaseYear')::integer not between 1950 and 2030 or jsonb_typeof(p_data->'instrumental') is distinct from 'boolean' or jsonb_typeof(p_data->'vocals') is distinct from 'boolean' or jsonb_typeof(p_data->'explicit') is distinct from 'boolean' or ((p_data->>'instrumental')::boolean and (p_data->>'vocals')::boolean) then raise exception 'Complete the track metadata' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(p_data) e where e.key in ('title','description','genre','subgenre','moods','key') and (jsonb_typeof(e.value) is distinct from 'string' or e.value#>>'{}' is distinct from btrim(e.value#>>'{}'))) then raise exception 'Invalid metadata text' using errcode='22023';end if;
 if s.track_id is null and not exists(select 1 from submission_media.assets where id=s.working_master_id and technical_state='ready') then raise exception 'Validated master required before catalog draft creation' using errcode='22023';end if;
 if s.track_id is null then
  t:=gen_random_uuid();insert into public.tracks(id,artist_user_id,title,slug,description,genre,subgenre,moods,bpm,musical_key,duration_seconds,release_year,instrumental,vocals,explicit,status) values(t,s.owner_id,p_data->>'title','upload-'||t::text,p_data->>'description',p_data->>'genre',p_data->>'subgenre',string_to_array(p_data->>'moods',','),(p_data->>'bpm')::integer,p_data->>'key',(select ceil(duration_us::numeric/1000000)::integer from submission_media.assets where id=s.working_master_id),(p_data->>'releaseYear')::integer,(p_data->>'instrumental')::boolean,(p_data->>'vocals')::boolean,(p_data->>'explicit')::boolean,'draft');update submission_media.submissions set track_id=t where id=s.id;
 else
  t:=s.track_id;perform 1 from public.tracks where id=t and artist_user_id=s.owner_id and status='draft' for update;if not found then raise exception 'Submitted metadata requires the canonical review workflow' using errcode='42501';end if;
  update public.tracks set title=p_data->>'title',description=p_data->>'description',genre=p_data->>'genre',subgenre=p_data->>'subgenre',moods=string_to_array(p_data->>'moods',','),bpm=(p_data->>'bpm')::integer,musical_key=p_data->>'key',release_year=(p_data->>'releaseYear')::integer,instrumental=(p_data->>'instrumental')::boolean,vocals=(p_data->>'vocals')::boolean,explicit=(p_data->>'explicit')::boolean where id=t;
 end if;
 perform submission_media.append_event(s.id,'upload_metadata_saved',null,o.id,null,null,'artist');return submission_media.finish_operation(o.id,jsonb_build_object('track_id',t,'revision',submission_media.bump(s.id)));end$function$

CREATE OR REPLACE FUNCTION public.media_upload_submit(p_submission uuid, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare s submission_media.submissions;o submission_media.operations;r jsonb;prior_status public.track_status;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);o:=submission_media.begin_operation(s.id,'submit_uploads',p_key,jsonb_build_object('revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if s.track_id is null or s.working_master_id is null or s.accepted_preview_id is null or not exists(select 1 from submission_media.assets where id=s.working_master_id and technical_state='ready') or not exists(select 1 from submission_media.assets where source_asset_id=s.working_master_id and kind='waveform' and technical_state='ready') or exists(select 1 from submission_media.upload_files f join submission_media.assets a on a.id=f.asset_id where f.submission_id=s.id and f.retired_at is null and a.technical_state<>'ready') then raise exception 'Validated Master, waveform, accepted Preview and complete uploads required' using errcode='22023';end if;
 select status into prior_status from public.tracks where id=s.track_id and artist_user_id=s.owner_id for update;
 if prior_status is null or prior_status not in ('draft','pending_review','approved') then raise exception 'Track unavailable for review' using errcode='42501';end if;
 if prior_status<>'approved' then update public.tracks set duration_seconds=(select ceil(duration_us::numeric/1000000)::integer from submission_media.assets where id=s.working_master_id),status='pending_review' where id=s.track_id and artist_user_id=s.owner_id;end if;
 r:=public.media_request_master_review(s.id,s.working_master_id,s.accepted_preview_id,s.revision,gen_random_uuid());return submission_media.finish_operation(o.id,r||jsonb_build_object('track_id',s.track_id,'is_resubmission',prior_status<>'draft'));end$function$

CREATE OR REPLACE FUNCTION public.media_submission_prepare(p_submission uuid, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions;o submission_media.operations;d jsonb;m jsonb;c jsonb;r jsonb;t uuid;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);
 o:=submission_media.begin_operation(s.id,'prepare_workspace',p_key,jsonb_build_object('revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or p_revision<>s.revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 d:=s.workspace_draft;if d is null then raise exception 'Save track details first' using errcode='22023';end if;
 perform submission_media.validate_master_owners(d->'masterOwners',true);
 perform submission_media.validate_workspace_rights(s.id,d,true);
 m:=jsonb_build_object('title',btrim(d->>'title'),'description',btrim(d->>'description'),'genre',btrim(d->>'genre'),'subgenre',btrim(d->>'subgenre'),'moods',btrim(d->>'moods'),'bpm',(d->>'bpm')::integer,'key',btrim(d->>'key'),'releaseYear',(d->>'releaseYear')::integer,'instrumental',d->>'vocal'='instrumental','vocals',d->>'vocal' in ('vocal','mixed'),'explicit',d->>'explicit'='explicit');
 r:=public.media_upload_save_metadata(s.id,m,s.revision,gen_random_uuid());t:=(r->>'track_id')::uuid;
 -- Preserve independently edited canonical catalog records. This bridge only seeds a new case.
 if not exists(select 1 from catalog_private.cases where track_id=t) then
  c:=catalog_private.initial_metadata(t)||jsonb_build_object('moods',coalesce((select jsonb_agg(tag order by tag) from (select min(btrim(value)) tag from regexp_split_to_table(d->>'moods',',') value where btrim(value)<>'' group by lower(btrim(value))) tags),'[]'::jsonb),'artist',btrim(d->>'primaryArtist'),'releaseTitle',btrim(d->>'releaseTitle'),'releaseStatus',d->>'releaseStatus','releaseDate',d->>'releaseDate','language',d->>'language','explicit',d->>'explicit','vocal',d->>'vocal','credits',
   jsonb_build_array(jsonb_build_object('name',btrim(d->>'primaryArtist'),'role','primary_artist')) ||
   coalesce((select jsonb_agg(jsonb_build_object('name',btrim(name),'role','featured_artist')) from regexp_split_to_table(d->>'featuredArtists',',') name where btrim(name)<>''),'[]'::jsonb) || (d->'contributors'));
  perform public.catalog_save(t,0,gen_random_uuid(),c);
 end if;
 return submission_media.finish_operation(o.id,jsonb_build_object('track_id',t,'revision',(select revision from submission_media.submissions where id=s.id)));
end $function$

CREATE OR REPLACE FUNCTION catalog_private.validate(p jsonb, p_complete boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare k text;v jsonb;allowed text[]:=array['title','artist','credits','description','releaseTitle','releaseStatus','releaseDate','releaseYear','genre','subgenre','moods','bpm','musicalKey','durationSeconds','explicit','vocal','language','isrc','iswc','recordingIdentifier','workIdentifier','keywords'];begin
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>40000 or p-allowed<>'{}' or not(p ?& allowed) then raise exception 'Structured bounded catalog metadata required' using errcode='22023';end if;
 foreach k in array array['title','artist','description','releaseTitle','releaseStatus','releaseDate','genre','subgenre','musicalKey','explicit','vocal','language','isrc','iswc','recordingIdentifier','workIdentifier'] loop
  if jsonb_typeof(p->k) is distinct from 'string' or p->>k<>btrim(p->>k) or (case when k='description' then translate(p->>k,chr(9)||chr(10)||chr(13),'') else p->>k end)~'[[:cntrl:]]' or length(p->>k)>(case when k='description' then 3000 else 200 end) then raise exception 'Invalid catalog text: %',k using errcode='22023';end if;
 end loop;
 if p->>'releaseStatus' not in('unreleased','released') or p->>'explicit' not in('unknown','clean','explicit') or p->>'vocal' not in('unknown','instrumental','vocal','mixed') or length(p->>'language')>35 or (p->>'language'<>'' and p->>'language'!~'^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$' and p->>'language'<>'zxx') or (p->>'isrc'<>'' and p->>'isrc'!~'^[A-Z]{2}[A-Z0-9]{3}[0-9]{7}$') or (p->>'iswc'<>'' and p->>'iswc'!~'^T[0-9]{10}$') then raise exception 'Invalid classification, language or identifier' using errcode='22023';end if;
 if p->>'musicalKey'<>'' and p->>'musicalKey'!~'^([A-G](#|b)?(m| (major|minor))?|atonal|unknown)$' then raise exception 'Invalid musical key' using errcode='22023';end if;
 if p->>'releaseDate'<>'' then if p->>'releaseDate'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or to_char((p->>'releaseDate')::date,'YYYY-MM-DD')<>p->>'releaseDate' then raise exception 'Invalid release date' using errcode='22023';end if;end if;
 foreach k in array array['releaseYear','bpm','durationSeconds'] loop
  if p->k<>'null'::jsonb and (jsonb_typeof(p->k)<>'number' or p->>k!~'^[0-9]{1,5}$') then raise exception 'Invalid numeric metadata' using errcode='22023';end if;
 end loop;
 if p->'durationSeconds'='null' or (p->>'durationSeconds')::int not between 0 and 36000 or p->'bpm'<>'null' and (p->>'bpm')::int not between 1 and 400 or p->'releaseYear'<>'null' and (p->>'releaseYear')::int not between 1900 and 2200 then raise exception 'Catalog value out of range' using errcode='22023';end if;
 foreach k in array array['moods','keywords','credits'] loop
  if jsonb_typeof(p->k) is distinct from 'array' or jsonb_array_length(p->k)>50 then raise exception 'Bounded catalog lists required' using errcode='22023';end if;
  for v in select value from jsonb_array_elements(p->k) loop
   if k='credits' then
    if jsonb_typeof(v) is distinct from 'object' or v-array['name','role']<>'{}' or jsonb_typeof(v->'name') is distinct from 'string' or jsonb_typeof(v->'role') is distinct from 'string' or length(v->>'name') not between 0 and 200 or v->>'name'<>btrim(v->>'name') or v->>'name'~'[[:cntrl:]]' or v->>'role' not in('primary_artist','featured_artist','composer','writer','producer','performer','publisher','other') then raise exception 'Invalid public credit' using errcode='22023';end if;
   elsif jsonb_typeof(v)<>'string' or length(v#>>'{}') not between 1 and 80 or v#>>'{}'<>btrim(v#>>'{}') or v#>>'{}'~'[[:cntrl:]]' then raise exception 'Invalid catalog tag' using errcode='22023';end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(p->k) e group by lower(e.value::text) having count(*)>1) then raise exception 'Duplicate metadata item' using errcode='22023';end if;
 end loop;
 if p->>'releaseDate'<>'' and (p->>'releaseYear')::int is distinct from extract(year from (p->>'releaseDate')::date)::int then raise exception 'Release year and date disagree' using errcode='22023';end if;
 if p_complete and (length(p->>'title')<2 or length(p->>'artist')<2 or length(p->>'genre')<2 or length(p->>'recordingIdentifier')<2 or length(p->>'workIdentifier')<2 or p->>'explicit'='unknown' or p->>'vocal'='unknown' or p->>'language'='' or (jsonb_array_length(p->'credits')=0 or exists(select 1 from jsonb_array_elements(p->'credits') credit where length(credit->>'name')=0)) or (p->>'durationSeconds')::int=0 or p->>'releaseStatus'='released' and p->>'releaseDate'='') then raise exception 'Complete identity, credits, classification and release metadata required' using errcode='22023';end if;
end$function$
